/**
 * sync-personal-finance-schedule.js
 *
 * Reads personal-finance-schedule-90day.xlsx (generated by
 * scripts/build-personal-finance-schedule.py, project root) and pushes its
 * rows into the live ContentEngine Google Sheet — the same sheet
 * publish-blog.js / publish-location.js actually read from.
 *
 * WHY THIS SCRIPT EXISTS (not just importing the xlsx into Sheets directly):
 * the planning spreadsheet uses a simple 15-column layout (A-O) meant for
 * human review. The live ContentEngine sheet uses a wider 26-column
 * contract (A-Z — service, contentBrief, internalLinkService, faqRequired,
 * linkedInRequired, author, etc. — see buildBlogRow/buildLocationRow in
 * seed-content-engine.js) that publish-blog.js's getScheduledRow() actually
 * parses. Pasting the simple sheet straight into the live tab would put
 * "Author" values in the "category" column and leave everything from
 * contentBrief onward blank. This script does the real mapping instead.
 *
 * Dedupes against existing sheet rows by slug before appending — safe to
 * run more than once (e.g. after re-generating the spreadsheet).
 *
 * ⚠ IMPORTANT — READ BEFORE RUNNING:
 * publish-blog.yml currently hardcodes SERVICE_FILTER: "Bridging Finance",
 * so the blog-publishing workflow will NOT pick up any row this script adds
 * (their `service` column is the pillar name, e.g. "Buying a Home", not
 * "Bridging Finance"). publish-location.yml has no such filter and WILL
 * pick up the location rows. Before running this for real, decide how
 * personal-finance blog posts should actually get published — e.g. a
 * separate scheduled workflow with its own cadence, rather than widening
 * SERVICE_FILTER and letting personal-finance content compete with bridging
 * for the single daily blog slot that was deliberately narrowed down
 * earlier this week. This script only populates the sheet; it does not
 * change any publishing workflow.
 *
 * Run: node sync-personal-finance-schedule.js [--dry-run] [--file=path.xlsx]
 */

require('dotenv').config();
const fs = require('fs');
const path = require('path');
const XLSX = require('xlsx');
const { google } = require('googleapis');

const SPREADSHEET_ID = process.env.SPREADSHEET_ID;

// Maps each personal-finance pillar to the most relevant existing Boxx
// commercial service page — these pillars have no /funding-solutions/ page
// of their own, so every article needs to funnel somewhere real. Must stay
// in sync with the `funnel_url`/`funnel_service` values in
// build-personal-finance-schedule.py's PILLARS dict.
const PILLAR_TO_SERVICE = {
  'Buying a Home': { service: 'Bridging Loans', url: '/funding-solutions/bridging-loans' },
  'Remortgaging': { service: 'Bridging Loans', url: '/funding-solutions/bridging-loans' },
  'Bad Credit and Debt': { service: 'Bridging Loans', url: '/funding-solutions/bridging-loans' },
  'Property Investing for Beginners': { service: 'Bridging Loans', url: '/funding-solutions/bridging-loans' },
  'Saving and Building Wealth': { service: 'Funding Solutions', url: '/funding-solutions' },
  'Legal and Conveyancing': { service: 'Bridging Loans', url: '/funding-solutions/bridging-loans' },
  'Property News and Market Updates': { service: 'Funding Solutions', url: '/funding-solutions' },
  'Taxes and Property': { service: 'Commercial Mortgages', url: '/funding-solutions/commercial-mortgages' },
};

async function getSheetsClient() {
  let credentials;
  if (process.env.GOOGLE_CREDENTIALS) {
    try { credentials = JSON.parse(Buffer.from(process.env.GOOGLE_CREDENTIALS, 'base64').toString('utf8')); }
    catch { credentials = JSON.parse(process.env.GOOGLE_CREDENTIALS); }
  }
  const auth = credentials
    ? new google.auth.GoogleAuth({ credentials, scopes: ['https://www.googleapis.com/auth/spreadsheets'] })
    : new google.auth.GoogleAuth({ keyFile: 'google-credentials.json', scopes: ['https://www.googleapis.com/auth/spreadsheets'] });
  return google.sheets({ version: 'v4', auth });
}

// ─── Read the planning spreadsheet's simple A-O layout ────────────────────────
function readScheduleFile(filePath) {
  const wb = XLSX.readFile(filePath);
  const ws = wb.Sheets['ContentEngine'];
  if (!ws) throw new Error(`No "ContentEngine" sheet found in ${filePath}`);
  // Row 1 = title banner, Row 2 = headers, data starts row 3 (1-indexed) —
  // sheet_to_json with range:2 skips both and reads from row 3 using our
  // own header list, since row 2's merged/styled headers don't reliably
  // round-trip as clean keys.
  const HEADERS = ['id', 'type', 'status', 'publishDate', 'slot', 'pillar', 'city',
    'keyword', 'topic', 'title', 'slug', 'url', 'metaTitle', 'metaDescription', 'author'];
  return XLSX.utils.sheet_to_json(ws, { header: HEADERS, range: 2, defval: '' });
}

// ─── Build a live-sheet row (A-Z, 26 cols) from a planning-sheet row ──────────
function toLiveRow(row) {
  const pillar = row.pillar;
  const funnel = PILLAR_TO_SERVICE[pillar] || PILLAR_TO_SERVICE['Saving and Building Wealth'];
  const type = String(row.type).toLowerCase(); // 'blog' | 'location'
  const isBlog = type === 'blog';

  return [
    `PF${row.id}`,                     // A id — PF prefix to distinguish from bridging's BF ids
    type,                              // B type
    'scheduled',                       // C status
    row.publishDate,                   // D publishDate
    isBlog ? (row.slot === 'Blog 1' ? 'AM' : 'PM') : '', // E publishSlot
    pillar,                            // F service (pillar name — see SERVICE_FILTER note above)
    isBlog ? '' : row.city.replace(', UK', ''), // G city
    row.keyword,                       // H keyword
    row.topic,                         // I topic
    row.title,                         // J title
    row.slug,                          // K slug
    '',                                // L url (filled after publish)
    row.metaTitle,                     // M metaTitle
    row.metaDescription,               // N metaDescription
    pillar,                            // O category
    '',                                // P contentBrief
    funnel.url,                        // Q internalLinkService
    '', '', '',                        // R-T internalLinkCity1-3
    '', '', '',                        // U-W relatedBlog1-3
    'yes',                             // X faqRequired
    isBlog ? 'yes' : 'no',             // Y linkedInRequired
    row.author,                        // Z author
  ];
}

async function main() {
  const isDryRun = process.argv.includes('--dry-run');
  const fileArg = process.argv.find(a => a.startsWith('--file='));
  const filePath = fileArg ? fileArg.split('=')[1] : path.resolve(__dirname, '../../personal-finance-schedule-90day.xlsx');

  console.log('\n╔══════════════════════════════════════════════════════════╗');
  console.log('║   Boxx Finance — Personal Finance Schedule Sync           ║');
  console.log('╚══════════════════════════════════════════════════════════╝\n');
  if (isDryRun) console.log('⚠  DRY RUN — no changes written\n');

  if (!fs.existsSync(filePath)) {
    console.error(`File not found: ${filePath}`);
    console.error('Run scripts/build-personal-finance-schedule.py first.');
    process.exit(1);
  }
  console.log(`Reading: ${filePath}`);
  const rows = readScheduleFile(filePath);
  console.log(`Rows in spreadsheet: ${rows.length}\n`);

  const sheets = await getSheetsClient();

  console.log('Fetching existing ContentEngine rows for dedupe...');
  const res = await sheets.spreadsheets.values.get({
    spreadsheetId: SPREADSHEET_ID,
    range: 'ContentEngine!K2:K', // slug column
  });
  const existingSlugs = new Set((res.data.values || []).map(r => (r[0] || '').trim()).filter(Boolean));
  console.log(`Existing slugs in sheet: ${existingSlugs.size}\n`);

  const newRows = [];
  let skipped = 0;
  for (const row of rows) {
    if (!row.slug || existingSlugs.has(row.slug)) { skipped++; continue; }
    newRows.push(toLiveRow(row));
    existingSlugs.add(row.slug); // guard against duplicate slugs within the file itself
  }

  console.log(`New rows to add: ${newRows.length}`);
  console.log(`Skipped (already in sheet or missing slug): ${skipped}\n`);

  if (newRows.length === 0) {
    console.log('✅ Nothing to add.\n');
    return;
  }

  console.log('── Preview (first 5) ────────────────────────────────────────');
  newRows.slice(0, 5).forEach(r => console.log(`  ${r[0]}  ${r[1]}  ${r[3]}  ${r[5]}  "${r[9]}"`));
  console.log('');

  if (isDryRun) {
    console.log('[DRY RUN] No changes written. Re-run without --dry-run to apply.\n');
    return;
  }

  await sheets.spreadsheets.values.append({
    spreadsheetId: SPREADSHEET_ID,
    range: 'ContentEngine!A:Z',
    valueInputOption: 'RAW',
    insertDataOption: 'INSERT_ROWS',
    requestBody: { values: newRows },
  });

  console.log(`✅ Appended ${newRows.length} rows to ContentEngine tab.\n`);
  console.log('Reminder: publish-location.yml will start picking these up automatically.');
  console.log('publish-blog.yml will NOT, until its SERVICE_FILTER is addressed — see the');
  console.log('note at the top of this file.\n');
}

main().catch(err => { console.error('Fatal:', err.message); process.exit(1); });
